<?php require_once 'config/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pw=$_POST['password']??'';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pw)>=8){try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);flash('Account created! Please log in.');redirect('login.php');}catch(PDOException $e){$err='That email address is already registered.';}}else $err='Enter valid details and a password of at least 8 characters.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Sign up | MindSpace</title></head><body class="auth"><div class="auth-card"><div class="brand">☁ MindSpace</div><h2>Start your personal space</h2><p class="muted">Create an account to keep your thoughts safe.</p><?php if(!empty($err))echo '<div class="flash">'.h($err).'</div>';?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="field"><label>Your name</label><input name="name" required></div><div class="field"><label>Email address</label><input type="email" name="email" required></div><div class="field"><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required></div><button>Create Account</button></form><p class="muted">Already registered? <a href="login.php">Login</a></p></div></body></html>
